# mark segments between aligned points, including endpoints
marks={2:[(1,0),(1,4),(3,0)],3:[(0,2),(4,2)]}
filled={}
for color,pts in marks.items():
    for i,p in enumerate(pts):
        for q in pts[i+1:]:
            if p[0]==q[0]:
                for c in range(min(p[1],q[1]),max(p[1],q[1])+1): filled[(p[0],c)]=filled.get((p[0],c),set())|{color}
            elif p[1]==q[1]:
                for r in range(min(p[0],q[0]),max(p[0],q[0])+1): filled[(r,p[1])]=filled.get((r,p[1]),set())|{color}
print([[6 if len(filled.get((r,c),set()))>1 else next(iter(filled[(r,c)])) if (r,c) in filled else 0 for c in range(6)] for r in range(6)])
